  const dobro = n * 2;
  return dobro;
}

function mostrarDobro(n) {
  calcular(n);
  return dobro;
}

let total = 0;

function somaDosQuadrados(n) {
  for (let i = 1; i <= n; i++) {
    total += i * i;
  }
  return total;
}

